def isPeakValley (lst : List Int) (h_precond : isPeakValley_precond (lst)) : Bool :=
  if lst.length < 3 then false
  else
    let inc_part := List.takeWhile (fun i => i < lst.length - 1) (List.range lst.length) |>.filter (fun i => lst.get! i < lst.get! (i + 1))
    let dec_part := List.takeWhile (fun i => i < lst.length - 1) (List.range lst.length) |>.filter (fun i => lst.get! i > lst.get! (i + 1))
    if inc_part.length = 0 ∨ dec_part.length = 0 then false
    else if inc_part.foldl (fun acc i => if i = 0 then lst.length - 1 - dec_part.length else acc) 0 < lst.length - 1 then true else false
